using System.Windows;using System.Windows.Media;using RAWSelectionAssistant.Core.Services.Projects;using RAWSelectionAssistant.ViewModels;
namespace RAWSelectionAssistant.Views;
public sealed partial class StudioViewingTableView
{
 async Task<ViewingFrame?> ResultFrameAsync(){if(workspace.LastViewingFilmResult is not Guid id)return null;var frame=workspace.ViewingFrames.FirstOrDefault(f=>f.Item.VariantId==id);if(frame is not null)return frame;var target=workspace.Targets.FirstOrDefault(t=>t.EditVersions.Any(v=>v.Id==id));var version=target?.EditVersions.Single(v=>v.Id==id);if(target?.SourceHash is null||version is null)return null;var item=new ViewingTableItem(target.Id,id,target.SourceHash,FilmBackendBindingV1.HashRecipe(version),version,0,0);var request=BeginRequest();try{var image=await workspace.RenderViewingItemAsync(item,1600,request.Cancellation.Token);return Current(request)?new ViewingFrame(item,image,"代理"):null;}finally{Finish(request);}}
 async Task ShowResultAsync(){var frame=await ResultFrameAsync();if(frame is null)return;selected=frame;await ShowDetailAsync();}
 async Task ReturnResultAsync(){var frame=await ResultFrameAsync();if(frame is null)return;selected=frame;await ReturnToDarkroomAsync();}
 internal async Task CompareResultAsync(){var result=await ResultFrameAsync();if(result is null||closed)return;var sourceId=result.Item.FrozenVariant.FilmBackend?.SourceVariantId;var source=workspace.LastViewingFilmCompletion is{} completion&&completion.ResultId==result.Item.VariantId?completion.FrozenSource:workspace.ViewingTable.Items.FirstOrDefault(i=>i.TargetId==result.Item.TargetId&&i.VariantId==sourceId&&i.RecipeHash==result.Item.FrozenVariant.FilmBackend?.SourceRecipeSha256);if(source is null&&sourceId is Guid frozenId){var target=workspace.Targets.FirstOrDefault(t=>t.Id==result.Item.TargetId);var version=target?.EditVersions.FirstOrDefault(v=>v.Id==frozenId);if(version is not null&&FilmBackendBindingV1.HashRecipe(version)==result.Item.FrozenVariant.FilmBackend?.SourceRecipeSha256)source=new ViewingTableItem(result.Item.TargetId,frozenId,result.Item.SourceHash,FilmBackendBindingV1.HashRecipe(version),version,0,0);}
 if(source is null){ShowFeedback("来源固定快照不可用，未替换为其他照片");return;}var request=BeginRequest();try{var image=await workspace.RenderViewingItemAsync(source,1600,request.Cancellation.Token);if(!Current(request))return;var view=new StudioSharedComparisonView();view.SetFrames([new(source.VariantId,"来源 · "+source.FrozenVariant.Name,image),new(result.Item.VariantId,"新变体 · "+result.Item.FrozenVariant.Name,result.Image)]);LastComparisonVariants=[source.VariantId,result.Item.VariantId];detail.Content=view;detail.Visibility=Visibility.Visible;}finally{Finish(request);}}
}
